import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import UnifiedNavbar from "../components/UnifiedNavbar";
import API from "../services/api";

function StudentDashboard(){

const [todayAttendance, setTodayAttendance] = useState(null);
const [attendanceStats, setAttendanceStats] = useState({ present: 0, absent: 0, leave: 0 });
const [loading, setLoading] = useState(true);

const storedUser = localStorage.getItem("user");
const studentId = storedUser ? JSON.parse(storedUser).id : null;

useEffect(() => {
  fetchData();
}, []);

const fetchData = async () => {
  try {
    setLoading(true);
    
    // Fetch today's attendance
    const today = new Date().toISOString().split('T')[0];
    try {
      const todayRes = await API.get(`/attendance/${studentId}/${today}`);
      setTodayAttendance(todayRes.data?.status || null);
    } catch (e) {
      setTodayAttendance(null);
    }

    // Fetch attendance history for stats
    try {
      const historyRes = await API.get(`/attendance`, {
        params: { studentId }
      });
      const records = historyRes.data || [];
      const stats = {
        present: records.filter(a => a.status === "Present").length,
        absent: records.filter(a => a.status === "Absent").length,
        leave: records.filter(a => a.status === "Leave").length
      };
      setAttendanceStats(stats);
    } catch (e) {
      setAttendanceStats({ present: 0, absent: 0, leave: 0 });
    }
  } catch (error) {
    console.log("Error fetching data");
  } finally {
    setLoading(false);
  }
};

return(

<div className="dashboard">

<UnifiedNavbar />

<div className="main-content">

<h1>Student Dashboard</h1>

<div className="cards">

<div className="card">
<h3>Today's Attendance</h3>
<p className={`attendance-status ${todayAttendance?.toLowerCase() || "unmarked"}`}>
  {loading ? "Loading..." : (todayAttendance || "Not Marked")}
</p>
<Link to="/attendance" className="card-link">Mark Attendance</Link>
</div>

<div className="card">
<h3>Monthly Attendance</h3>
<div className="attendance-mini-stats">
  <span className="present">✓ {attendanceStats.present}</span>
  <span className="absent">✗ {attendanceStats.absent}</span>
  <span className="leave">📋 {attendanceStats.leave}</span>
</div>
<Link to="/attendance" className="card-link">View Details</Link>
</div>

<div className="card">
<h3>Meals Taken</h3>
<p>Breakfast + Lunch</p>
</div>

</div>

</div>

</div>

)

}

export default StudentDashboard
